        description: "天山,横亘新疆中部,西连帕米尔、东接河西走廊,长二千五百公里,是中国西陲之脊,亦古丝路南北两道之分界。北麓有伊犁、轮台、庭州;南麓有龟兹、于阗、楼兰。汉以来历代望此山者无数 —— 张骞、班超、玄奘、岑参、林则徐 —— 而能登者寥寥。山见之下,丝路诸国先后兴亡;山色之上,雪线万古未变。望天山者,所望非山,乃中华西陲两千年之沧桑。",
