                quote: "鄯善国,本名楼兰,王治扜泥城,去阳关千六百里,去长安六千一百里。户千五百七十,口万四千一百,胜兵二千九百十二人。地沙卤,少田,寄田仰谷旁国。国出玉,多葭苇、柽柳、胡桐、白草。民随畜牧,逐水草,有驴马,多橐它。能作兵,与婼羌同。",
